// Package emit prints IR as deterministic, statically typed, erasable-
// syntax TypeScript: strict ESM with explicit .js relative imports,
// provenance headers, and fully parenthesized expressions so precedence is
// never ambiguous. Every integer operation lowers through the versioned
// language ABI unless the operation is exact under direct JS semantics.
package emit

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/tsoniclang/gotots/internal/ir"
)

// Provenance identifies the inputs of one generated file.
type Provenance struct {
	SchemaVersion  int    `json:"schemaVersion"`
	SourceRevision string `json:"sourceRevision"`
	ProfileHash    string `json:"profileHash"`
	AbiVersion     int    `json:"abiVersion"`
	Path           string `json:"path"`
	ContentHash    string `json:"contentHash"`
}

// FileWithProvenance prepends the deterministic provenance header; the
// content hash covers everything after the header block.
func FileWithProvenance(p Provenance, body string) (string, error) {
	digest := sha256.Sum256([]byte(body))
	p.ContentHash = hex.EncodeToString(digest[:])
	header, err := json.Marshal(p)
	if err != nil {
		return "", err
	}
	return "// Code generated by GoToTS for TSTS. DO NOT EDIT.\n" +
		"// @gotots-generated " + string(header) + "\n\n" + body, nil
}

// Method is one method whose receiver type has no generated class — a
// named type erased to its carrier — emitted as a standalone function.
type Method struct {
	TypeName string
	Fn       *ir.Func
}

// PackageVar is one package-level variable, generated as a module-level
// let whose exported form is a live ESM binding: declared with its zero
// value, then assigned in the type checker's initialization order.
type PackageVar struct {
	Name     string
	Type     ir.Type
	Init     ir.Expr
	Exported bool
	// Order is the initializer's position in types.Info.InitOrder, or -1
	// for variables with no initializer (their zero value stands).
	Order int
	// Blank marks a blank (_) variable: no binding declares, but the
	// initializer still runs in order for its effects.
	Blank bool
	// Placeholder marks a variable whose INITIALIZER is a recorded
	// unsupported construct: the binding still declares with its exact
	// type and zero value (the declaration surface stays whole, so the
	// package materializes and typechecks), and its initializer slot
	// becomes a typed throwing call carrying PlaceholderID — running it
	// fails closed, and the package is publication-withheld.
	Placeholder   bool
	PlaceholderID string
}

// CarrierType is one named non-struct type: erased to its carrier, it
// still owns an rtti object (and possibly methods) for interface use.
type CarrierType struct {
	Name     string
	Exported bool
	// Underlying is the carrier's resolved value type; the module
	// declares `export type Name = <underlying>` so union members and
	// signatures can reference the named carrier directly.
	Underlying ir.Type
}

// Decls is the complete declaration set of one translated package.
type Decls struct {
	Structs      []*ir.Struct
	Methods      []Method
	CarrierTypes []CarrierType
	Vars         []PackageVar
	Functions    []*ir.Func
	// InitCalls names the package's init functions in Go's execution
	// order (file order, then position), invoked at module evaluation
	// after every variable initializer.
	InitCalls []string
}

// printer carries per-function emission state and the module context.
type printer struct {
	out    *strings.Builder
	module *Module
	indent int
	temps  int
	// rangeBreak, when set, transforms break inside a range-over-func
	// body into the yield protocol; nested loops and switches (which own
	// their own break) clear it.
	rangeBreak *rangeFuncCtx
	// rangeContinue transforms continue likewise; only nested loops
	// (which own continue) clear it — switches do not.
	rangeContinue *rangeFuncCtx
	// rangeReturn, when set, transforms function returns anywhere inside
	// a range-over-func yield closure into the captured-return protocol;
	// only a nested function literal clears it.
	rangeReturn *rangeFuncCtx
	// pendingLoopLabel is a Go label awaiting its loop or switch line
	// (multi-statement lowerings put their temps before it, so the label
	// binds the actual loop and continue-label works).
	pendingLoopLabel string
	// zeroFactories maps in-scope type parameters to their zero-factory
	// parameter names while a generic goZero$ body prints.
	zeroFactories map[string]string
	// eqOps maps in-scope type parameters to their equality-operation
	// parameter names while a generic body prints.
	eqOps map[string]string
	// cloneOps / setOps map in-scope type parameters to their copy-factory
	// parameter names: clone$P is the TOTAL per-binding copy (identity for
	// carriers without value-copy semantics) and set$P is the in-place
	// overwrite (undefined for slot-assignment carriers).
	cloneOps map[string]string
	setOps   map[string]string
	// slicePlans maps this body's slice-typed locals to their selected
	// representation; "native-array" locals lower onto plain arrays.
	slicePlans map[string]string
	// normBreak / normContinue redirect break / continue when the
	// innermost loop is a normalized for-loop (multi-result clause):
	// break becomes `break brk$N` and continue becomes `break cont$N`
	// so the post statement still runs. They mirror rangeBreak /
	// rangeContinue: a nested loop clears both, a switch clears only
	// normBreak (continue still targets the loop).
	normBreak    *normLoopCtx
	normContinue *normLoopCtx
	// normLabels maps a normalized loop's Go label (spelled) to its
	// context so a labeled break/continue targeting it redirects too.
	normLabels map[string]*normLoopCtx
	// loopSeq numbers normalized loops within this body for unique,
	// deterministic break/continue labels.
	loopSeq int
}

// normLoopCtx carries a normalized for-loop's redirect labels: break
// exits the while (breakLabel) and continue exits the body block so the
// post statement runs (contLabel).
type normLoopCtx struct {
	breakLabel string
	contLabel  string
}

// nativeSlice reports whether the expression reads a local whose region
// selected the native-array representation.
func (p *printer) nativeSlice(e ir.Expr) bool {
	ref, isVar := e.(*ir.VarRef)
	return isVar && ref.Pkg == "" && p.slicePlans[ref.Name] == "native-array"
}

// takeLoopLabel consumes the pending label as a "name: " prefix.
func (p *printer) takeLoopLabel() string {
	if p.pendingLoopLabel == "" {
		return ""
	}
	label := p.pendingLoopLabel
	p.pendingLoopLabel = ""
	return label + ": "
}

// rangeFuncCtx carries one range-over-func loop's protocol variables.
type rangeFuncCtx struct {
	doneVar     string
	returnedVar string
	retVar      string // "" when the enclosing function returns nothing
	// returnUsed marks that a body return actually set the flag: the
	// propagated-return epilogue is emitted only then.
	returnUsed bool
}

func (p *printer) line(format string, args ...any) {
	p.out.WriteString(strings.Repeat("  ", p.indent))
	fmt.Fprintf(p.out, format, args...)
	p.out.WriteString("\n")
}

func (p *printer) temp() string {
	name := fmt.Sprintf("_t%d$", p.temps)
	p.temps++
	return name
}

func printFunc(out *strings.Builder, module *Module, function *ir.Func) error {
	p := &printer{out: out, module: module}
	signature, err := p.functionSignature(function)
	if err != nil {
		return fmt.Errorf("%s: %w", function.ID, err)
	}
	export := "export "
	generics := ""
	if len(function.TypeParams) > 0 {
		generics = "<" + strings.Join(function.TypeParams, ", ") + ">"
	}
	p.slicePlans = function.SlicePlans
	p.line("%sfunction %s%s%s {", export, tsName(function.Name), generics, signature)
	p.indent++
	if len(function.TypeParams) > 0 {
		p.zeroFactories = map[string]string{}
		p.eqOps = map[string]string{}
		p.cloneOps = map[string]string{}
		p.setOps = map[string]string{}
		for _, param := range function.TypeParams {
			p.zeroFactories[param] = "zero$" + param
			p.eqOps[param] = "eq$" + param
			p.cloneOps[param] = "clone$" + param
			p.setOps[param] = "set$" + param
		}
	}
	if function.Placeholder {
		p.printPlaceholderBody(function.ID)
	} else if err := p.printDeferWrappedBody(function.Body, function.UsesDeferStack); err != nil {
		return fmt.Errorf("%s: %w", function.ID, err)
	}
	p.indent--
	p.line("}")
	return nil
}

// printPlaceholderBody emits the fail-closed body of a materialized
// placeholder: a single call to the never-returning ABI helper, so the
// declaration typechecks against any declared return type while calling it
// fails closed with the body's exact identity.
func (p *printer) printPlaceholderBody(id string) {
	p.line("gort$.goBodyUnimplemented(%q);", id)
}

func (p *printer) functionSignature(function *ir.Func) (string, error) {
	var params []string
	for _, parameter := range function.Params {
		spelled, err := p.tsType(parameter.Type)
		if err != nil {
			return "", err
		}
		params = append(params, tsName(parameter.Name)+": "+spelled)
	}
	// A generic function takes one zero factory and one equality
	// operation per type parameter as trailing parameters: the
	// instantiation's exact zero and exact == (direct === for comparable
	// scalars, interface equality with the uncomparable panic for
	// interface instantiations).
	for _, param := range function.TypeParams {
		params = append(params, "zero$"+param+": () => "+param)
	}
	for _, param := range function.TypeParams {
		params = append(params, "eq$"+param+": (a: "+param+", b: "+param+") => boolean")
	}
	// Factory protocol v2: the per-binding copy operations. clone$P is
	// TOTAL (identity for carriers without value-copy semantics); set$P is
	// undefined exactly when the carrier stores by slot assignment.
	for _, param := range function.TypeParams {
		params = append(params, "clone$"+param+": (v: "+param+") => "+param)
	}
	for _, param := range function.TypeParams {
		params = append(params, "set$"+param+": ((d: "+param+", s: "+param+") => void) | undefined")
	}
	result, err := p.tsResultType(function.Results)
	if err != nil {
		return "", err
	}
	return "(" + strings.Join(params, ", ") + "): " + result, nil
}

// tsType spells the static TypeScript type of one IR type, qualifying
// named types from other unit packages with their module alias.
func (p *printer) tsType(t ir.Type) (string, error) {
	switch t.Kind {
	case ir.KindBool:
		return "boolean", nil
	case ir.KindString:
		return "string", nil
	case ir.KindFloat32, ir.KindFloat64:
		return "number", nil
	case ir.KindInt8:
		return "goabi$.GoInt8", nil
	case ir.KindInt16:
		return "goabi$.GoInt16", nil
	case ir.KindInt32:
		return "goabi$.GoInt32", nil
	case ir.KindInt64:
		return "goabi$.GoInt64", nil
	case ir.KindInt:
		return "goabi$.GoInt", nil
	case ir.KindUint8:
		return "goabi$.GoUint8", nil
	case ir.KindUint16:
		return "goabi$.GoUint16", nil
	case ir.KindUint32:
		return "goabi$.GoUint32", nil
	case ir.KindUint64:
		return "goabi$.GoUint64", nil
	case ir.KindUint:
		return "goabi$.GoUint", nil
	case ir.KindUintptr:
		return "goabi$.GoUintptr", nil
	case ir.KindPointer:
		if t.Elem != nil && t.Elem.Kind == ir.KindExternal {
			element, err := p.tsType(*t.Elem)
			if err != nil {
				return "", err
			}
			return element + " | undefined", nil
		}
		if t.Elem != nil && t.Elem.Kind == ir.KindArray {
			element, err := p.tsType(*t.Elem)
			if err != nil {
				return "", err
			}
			return element + " | undefined", nil
		}
		if t.Elem != nil && t.Elem.Kind != ir.KindStruct {
			element, err := p.tsType(*t.Elem)
			if err != nil {
				return "", err
			}
			return "gort$.GoCell<" + element + "> | undefined", nil
		}
		name, err := p.tsType(*t.Elem)
		if err != nil {
			return "", err
		}
		return name + " | undefined", nil
	case ir.KindStruct:
		name, err := p.module.symbol(t.Pkg, t.Named)
		if err != nil {
			return "", err
		}
		if len(t.TypeArgs) > 0 {
			args := make([]string, len(t.TypeArgs))
			for i, arg := range t.TypeArgs {
				if args[i], err = p.tsType(arg); err != nil {
					return "", err
				}
			}
			name += "<" + strings.Join(args, ", ") + ">"
		}
		return name, nil
	case ir.KindArray:
		element, err := p.tsType(*t.Elem)
		if err != nil {
			return "", err
		}
		if strings.Contains(element, "|") || strings.Contains(element, "=>") {
			// A union or function element must parenthesize: T | U[] is
			// not (T | U)[].
			element = "(" + element + ")"
		}
		return element + "[]", nil
	case ir.KindUnit:
		return "0", nil
	case ir.KindExternal:
		return fmt.Sprintf("goext$.GoExtern<%q>", t.Pkg+"."+t.Named), nil
	case ir.KindChan:
		return "(gort$.GoChanHandle | undefined)", nil
	case ir.KindIface:
		if t.TypeParamName != "" {
			return tsName(t.TypeParamName), nil
		}
		// Every interface position — in core modules AND external stub
		// modules — spells its EXACT closed member union (withheld
		// implementers filtered). There is no erased opaque supertype.
		return p.ifaceUnionAlias(t)
	case ir.KindTypeParam:
		return t.Named, nil
	case ir.KindFunc:
		var params []string
		for i, parameter := range t.Sig.Params {
			spelled, err := p.tsType(parameter)
			if err != nil {
				return "", err
			}
			params = append(params, fmt.Sprintf("p%d: %s", i, spelled))
		}
		resultVars := make([]ir.Var, len(t.Sig.Results))
		for i, result := range t.Sig.Results {
			resultVars[i] = ir.Var{Type: result}
		}
		result, err := p.tsResultType(resultVars)
		if err != nil {
			return "", err
		}
		return "((" + strings.Join(params, ", ") + ") => " + result + ") | undefined", nil
	case ir.KindSlice:
		element, err := p.tsType(*t.Elem)
		if err != nil {
			return "", err
		}
		return "gosl$.GoSliceValue<" + element + ">", nil
	case ir.KindMap:
		key, err := p.tsType(*t.Key)
		if err != nil {
			return "", err
		}
		value, err := p.tsType(*t.Elem)
		if err != nil {
			return "", err
		}
		if t.Key.Kind == ir.KindStruct {
			return "gort$.GoKeyedMap<" + key + ", " + value + ">", nil
		}
		if t.Key.Kind.Float() {
			return "gort$.GoFMap<" + value + ">", nil
		}
		return "gort$.GoMap<" + key + ", " + value + ">", nil
	}
	return "", fmt.Errorf("no TypeScript spelling for IR type %q", t.Go)
}

func (p *printer) tsResultType(results []ir.Var) (string, error) {
	switch len(results) {
	case 0:
		return "void", nil
	case 1:
		return p.tsType(results[0].Type)
	default:
		var parts []string
		for _, result := range results {
			spelled, err := p.tsType(result.Type)
			if err != nil {
				return "", err
			}
			parts = append(parts, spelled)
		}
		return "readonly [" + strings.Join(parts, ", ") + "]", nil
	}
}
